sys_ui_action.script:
// Populate ai_pre_assessment with a generated analysis
var analysis = '=== GenAI Pre-Assessment Output ===\n';
analysis += 'Assessment Date: ' + gs.nowDateTime() + '\n\n';

analysis += '--- Technical Fit Analysis ---\n';
analysis += 'Data Structure: ' + current.getValue('data_structure') + '\n';
analysis += 'Decision Logic: ' + current.getValue('decision_logic') + '\n';
analysis += 'Expected Resolution Rate: ' + current.getValue('expected_resolution_rate') + '%\n';
analysis += 'Contains PII: ' + current.getValue('contains_pii') + '\n\n';

analysis += '--- Financial Summary ---\n';
analysis += 'Current Annual Cost: ' + current.getValue('current_annual_cost') + '\n';
analysis += 'Build Effort: ' + current.getValue('build_effort') + '\n';
analysis += 'Monthly Run Cost: ' + current.getValue('monthly_run_cost') + '\n';
analysis += 'Year One Net ROI: ' + current.getValue('year_one_net_roi') + '\n\n';

analysis += '--- Recommendation ---\n';
var decisionLogic = current.getValue('decision_logic');
var containsPii = current.getValue('contains_pii');
if (decisionLogic == 'requires_judgment' && containsPii == 'true') {
    analysis += 'RECOMMENDATION: Private Enterprise LLM deployment required.\n';
    analysis += 'Rationale: Process requires judgement AND contains PII data.\n';
} else if (decisionLogic == 'strict_if_then') {
    analysis += 'RECOMMENDATION: Legacy RPA / Rule-based automation.\n';
    analysis += 'Rationale: Process follows strict if/then logic with no ambiguity.\n';
} else {
    analysis += 'RECOMMENDATION: Generative AI solution suitable.\n';
    analysis += 'Rationale: Process involves flexible decision-making appropriate for AI.\n';
}

current.setValue('ai_pre_assessment', analysis);
current.update();
